package in.aicon.pocket;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.json.*;

/** Validated ledger preferences. No authentication, tokens or device launcher state. */
public final class SettingsStore {
 private final SQLiteDatabase db;
 public static final String[] PALETTES={"Dynamic","Teal","Blue","Violet","Rose","Graphite"};
 public static final String[] CURRENCIES={"INR","USD","EUR","GBP","AED","SAR","SGD","MYR","CAD","AUD"};
 public static final String[] DATES={"yyyy-MM-dd","dd/MM/yyyy","MM/dd/yyyy","dd MMM yyyy"};
 public static final String[] HOME={"summary","quick","accounts","people","recent"};
 private static final Map<String,String> DEFAULTS=new LinkedHashMap<>();
 static {DEFAULTS.put("launcherIcon","Orange");DEFAULTS.put("dailyReminders","Off");DEFAULTS.put("font","System default");DEFAULTS.put("reminderMorning","510");DEFAULTS.put("reminderEvening","1230");DEFAULTS.put("palette","Dynamic");DEFAULTS.put("surface","Liquid Glass");DEFAULTS.put("pureBlack","Off");DEFAULTS.put("currency","INR");DEFAULTS.put("amountStyle","Symbol");DEFAULTS.put("grouping","Indian");DEFAULTS.put("dateFormat","yyyy-MM-dd");DEFAULTS.put("home","summary,quick,accounts,people,recent");DEFAULTS.put("defaultKind","expense");DEFAULTS.put("defaultAccount","");DEFAULTS.put("defaultCategory","");DEFAULTS.put("language","en");DEFAULTS.put("appearance","On device");}
 public SettingsStore(SQLiteDatabase db){this.db=db;db.execSQL("CREATE TABLE IF NOT EXISTS preferences(name TEXT PRIMARY KEY,value TEXT NOT NULL)");}
 public String get(String key){if(!DEFAULTS.containsKey(key))throw new IllegalArgumentException("Unknown preference");try(Cursor c=db.rawQuery("SELECT value FROM preferences WHERE name=?",new String[]{key})){return c.moveToFirst()?c.getString(0):DEFAULTS.get(key);}}
 public boolean has(String key){try(Cursor c=db.rawQuery("SELECT value FROM preferences WHERE name=?",new String[]{key})){return c.moveToFirst();}}
 public void put(String key,String value){validate(key,value);ContentValues v=new ContentValues();v.put("name",key);v.put("value",value);if(db.insertWithOnConflict("preferences",null,v,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new android.database.SQLException("Could not save preference");}
 public static void validate(String key,String value){if(!DEFAULTS.containsKey(key)||value==null)throw new IllegalArgumentException("Invalid preference");String[] allowed=null;switch(key){case "launcherIcon":allowed=AppIcon.COLORS;break;case "dailyReminders":allowed=new String[]{"On","Off"};break;case "font":allowed=AppFonts.CHOICES;break;case "reminderMorning":case "reminderEvening":if(!value.matches("[0-9]{1,4}")||Integer.parseInt(value)>1439)throw new IllegalArgumentException("Invalid reminder time");return;case "surface":allowed=new String[]{"Dynamic","Liquid Glass"};break;case "pureBlack":allowed=new String[]{"On","Off"};break;case "palette":allowed=PALETTES;break;case "currency":allowed=CURRENCIES;break;case "amountStyle":allowed=new String[]{"Symbol","Code"};break;case "grouping":allowed=new String[]{"Indian","International","None"};break;case "dateFormat":allowed=DATES;break;case "defaultKind":allowed=new String[]{"expense","income","lent","borrowed","transfer"};break;case "language":allowed=new String[]{"en","ml"};break;case "appearance":allowed=new String[]{"Light","Dark","On device"};break;case "defaultAccount":case "defaultCategory":if(!value.isEmpty())Identifiers.uuid(value);return;case "home":Set<String> seen=new HashSet<>();if(value.isEmpty())throw new IllegalArgumentException("Keep at least one home section");for(String section:value.split(",",-1))if(!Arrays.asList(HOME).contains(section)||!seen.add(section))throw new IllegalArgumentException("Invalid home sections");return;}if(allowed!=null&&!Arrays.asList(allowed).contains(value))throw new IllegalArgumentException("Invalid preference choice");}
 public JSONObject export()throws Exception{JSONObject j=new JSONObject();for(String key:DEFAULTS.keySet())j.put(key,get(key));return j;}
 public static void validateExport(JSONObject j)throws Exception{if(j.length()>DEFAULTS.size())throw new IllegalArgumentException("Unexpected preferences");Iterator<String> keys=j.keys();while(keys.hasNext()){String key=keys.next();Object value=j.get(key);if(!(value instanceof String))throw new IllegalArgumentException("Invalid preference value");validate(key,(String)value);}}
 static void validateReferences(JSONObject values,Map<String,String> entityTypes)throws Exception{for(String key:new String[]{"defaultAccount","defaultCategory"}){String id=values.optString(key,"");if(!id.isEmpty()&&!Objects.equals(entityTypes.get(id),key.equals("defaultAccount")?"account":"category"))throw new IllegalArgumentException("Quick-entry default points to a missing or wrong item. Review preferences before merging.");}}
 public void restore(JSONObject j)throws Exception{if(!db.inTransaction())throw new IllegalStateException("Preferences must share the restore transaction");validateExport(j);db.delete("preferences",null,null);for(String key:DEFAULTS.keySet())put(key,j.has(key)?j.getString(key):DEFAULTS.get(key));}
}
